'use strict';

function calculateInvoice(lines) {
  if (!Array.isArray(lines)) throw new TypeError('lines must be an array');
  const lineTotals = lines.map(line => {
    if (!line || !Number.isInteger(line.quantity) || line.quantity <= 0) throw new TypeError('invalid quantity');
    const raw = line.unitPrice;
    const validString = typeof raw === 'string' && /^(0|[1-9]\d*)(\.\d+)?$/.test(raw);
    if (!(typeof raw === 'number' && Number.isFinite(raw) && raw >= 0) && !validString) throw new TypeError('invalid unit price');
    const price = parseInt(raw, 10);
    return line.quantity * price;
  });
  return { subtotal: lineTotals.reduce((sum, value) => sum + value, 0), lineTotals };
}

