'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['calculateInvoice']);
const { calculateInvoice } = api;

assert.deepStrictEqual(calculateInvoice([]), { subtotal: 0, lineTotals: [] });
const lines = [
  { quantity: 2, unitPrice: '12.34' },
  { quantity: 3, unitPrice: 0.5 },
  { quantity: 4, unitPrice: '0.5' },
  { quantity: 1, unitPrice: '0' }
];
const snapshot = JSON.stringify(lines);
const result = calculateInvoice(lines);
assert.deepStrictEqual(result, {
  subtotal: 28.18,
  lineTotals: [24.68, 1.5, 2, 0]
});
assert.strictEqual(JSON.stringify(lines), snapshot);
assert.notStrictEqual(result.lineTotals, lines);
result.lineTotals[0] = 999;
assert.strictEqual(lines[0].unitPrice, '12.34');
assert.deepStrictEqual(calculateInvoice([{ quantity: 1, unitPrice: 0 }]), {
  subtotal: 0, lineTotals: [0]
});

for (const bad of [null, {}, 'lines']) {
  assert.throws(() => calculateInvoice(bad), TypeError);
}
for (const quantity of [0, -1, 1.5, NaN, Infinity, '2']) {
  assert.throws(() => calculateInvoice([{ quantity, unitPrice: 1 }]), TypeError);
}
for (const unitPrice of [
  -1, NaN, Infinity, -Infinity, null, {}, '', ' 1', '1 ', '+1', '-1',
  '1e2', '1.', '.5', '00', '01', '00.5', '12.340 '
]) {
  assert.throws(() => calculateInvoice([{ quantity: 1, unitPrice }]), TypeError);
}
assert.throws(() => calculateInvoice([null]), TypeError);

